"""Human-readable audit without reinterpreting unavailable states."""
from common import *
import pandas as pd

def main():
 f=frozen();c=pd.read_csv(OUT/'checkpoint_coverage.csv');h=pd.read_csv(OUT/'imp_history.csv');t=pd.read_csv(OUT/'historical_tickets.csv');missing=[]
 for j in f['conditions']:
  for step in STEPS:
   if step not in (0,2500,3000,4000,5000):missing.append(dict(condition=j['id'],step=step,kind='full_model_state',status='historically_unavailable'))
 table(OUT/'historical_missing_states.csv',missing)
 lines=['# Cohort and provenance audit','',f"Frozen cohort SHA256: `{sha(OUT/'cohort.json')}`. Frozen protocol SHA256: `{sha(OUT/'protocol.md')}`.",'',f"Ten sparse conditions and five distinct matched dense recoveries; {len(c)} checkpoint-role records and {len(f['files'])} registered files verified. {len(h)} IMP discovery stages across five seeds.",'','Each .80 mask is selected from round_07; each .85 mask from round_08. All nine rounds restart at original initialization, with fresh optimizer and trainable R0 router. The final sparse conditions restart separately with those exact masks. Dense comparators are canonical R0 dense recovery artifacts, not source-final training checkpoints. The source-final dense is only an additional reference.','',f"IMP discovery applied updates range {int(h.applied.min())}–{int(h.applied.max())} of 2500 attempts. Therefore attempted steps are not interchangeable with applied updates.",'','Full historical recovery states are available at 2500,3000,4000,5000. Recovery initialization is reconstructable exactly from verified original init and fixed mask, checked against saved component hashes. Early historical recovery intermediates are absent; router-only snapshots cannot replace them. Original source training has its own intermediate checkpoints; those are not recovery intermediates.','',f"{int(c.optimizer.sum())} checkpoint-role records contain optimizer state; {int(c.scaler.sum())} contain scaler state; {int(c.rng.sum())} contain all four RNG families. The 2500-step model-only boundary deliberately resets AdamW/scaler for BOTH sparse and dense continuations. Full extension checkpoints record training_data_position; no live sampler object was saved. Native materialized batches plus position and hashes define deterministic ordering.",'','Training: fixed 128 sequences ×128 byte tokens, 5000 attempted steps, 81920000 token presentations. Validation: original 32 materialized batches, sequence identity/hash checked. Validation participates in historical ticket selection and is not independent test. No demonstrably unused test split is established.','',f"Historical strict validation successes: {int(t.strict_success.sum())}/10 over {t[t.strict_success].seed.nunique()} source seeds, with related observations at two sparsities for seed 7. Continuous gaps retained:",'','```csv',t.to_csv(index=False).strip(),'```','','Full code/source history of the original source trainer was inspected; original source model-only checkpoints do not establish AMP skipped-update counts or exact optimizer/RNG continuation. Do not infer unrecorded source update counts. Source training is not rerun.','', 'Both-host verification results are stored in hosts/. GPU benchmark and validation results are separate launch gates. No historical directories are modified.']
 (OUT/'provenance_audit.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
